package com.frostsecurity.extreme.reports;
import com.frostsecurity.extreme.core.*; import com.google.gson.*; import java.nio.file.*; import java.time.Instant; import java.util.*;
public final class ReportGenerator { public static ReportData build(String scope){return new ReportData(UUID.randomUUID().toString(),Instant.now(),scope,"Análise passiva: metadados do cliente, telemetria de sessão e regras transparentes; sem exploração.",com.frostsecurity.extreme.recon.ServerProfile.current(),SecurityEngine.findings(),List.of("Um mod cliente não consegue confirmar configurações privadas do servidor sem dados fornecidos pelo proprietário."));}
 public static Path writeTxt(ReportData r,Path p)throws Exception{StringBuilder s=new StringBuilder("FROST SECURITY SCANNER EXTREME\n");s.append("ID: ").append(r.id()).append("\nData: ").append(r.generatedAt()).append("\nEscopo: ").append(r.scope()).append("\nMetodologia: ").append(r.methodology()).append("\nServidor: ").append(r.server().address()).append("\n\nACHADOS\n");for(SecurityFinding f:r.findings())s.append("["+f.severity()+"] "+f.id()+" - "+f.title()+" (confiança "+f.confidence()+")\n").append(f.explanation()).append("\n");s.append("\nLIMITAÇÕES\n");r.limitations().forEach(x->s.append("- ").append(x).append("\n"));Files.writeString(p,s.toString());return p;}
 public static Path writeJson(ReportData r,Path p)throws Exception{Files.writeString(p,new GsonBuilder().setPrettyPrinting().create().toJson(r));return p;}
 public static Path writeHtml(ReportData r,Path p)throws Exception{StringBuilder b=new StringBuilder("<!doctype html><html><head><meta charset='utf-8'><title>FROST Report</title><style>body{background:#081018;color:#dcecff;font:14px system-ui;padding:32px}h1{color:#59d8ff}.card{border:1px solid #20445c;padding:16px;margin:12px 0;border-radius:10px}code{color:#8fe9ff}</style></head><body><h1>FROST SECURITY SCANNER EXTREME</h1><p><code>");b.append(r.id()).append("</code> — ").append(r.generatedAt()).append("</p>");for(SecurityFinding f:r.findings())b.append("<div class='card'><b>").append(f.severity()).append(" — ").append(f.title()).append("</b><p>").append(f.explanation()).append("</p></div>");b.append("</body></html>");Files.writeString(p,b.toString());return p;}}
